-- Complete verified video catalog; adds Wan ratio and H3 reference / Grok preview routes.
on conflict (key) do update set name=excluded.name,provider=excluded.provider,provider_model_id=excluded.provider_model_id,media_type=excluded.media_type,credit_cost=excluded.credit_cost,provider_credit_cost=excluded.provider_credit_cost,description=excluded.description,badge=excluded.badge,parameter_schema=excluded.parameter_schema,provider_config=excluded.provider_config,credit_rules=excluded.credit_rules,is_active=excluded.is_active,sort_order=excluded.sort_order;

-- Single-prompt composer cannot supply the shot list required by Kling multi-shot mode.
update public.studio_models set parameter_schema=jsonb_set(parameter_schema, '{properties,multi_shots}', '{"type":"boolean","enum":[false]}'::jsonb) where key='kling-3-video';
-- First-frame controls accept one image; reject incompatible references before charging.
update public.studio_models set provider_config=provider_config || '{"minInputs":0,"maxInputs":1,"inputMimeTypes":["image/jpeg","image/png","image/webp"]}'::jsonb
where key in ('kling-3-video','wan-3-video','seedance-1-5-pro-720p-8s');
